-- bootlegger-coffee-company-century-city (owner)
UPDATE businesses SET description = 'Bootlegger Coffee Company in Century City is a specialty coffee café at Shop 5, 5 Esplanade Road. Part of the Cape Town-born Bootlegger group, the café is open seven days a week and serves all-day breakfast and lunch to the office workers, residents and visitors who fill the Century City precinct.

Coffee is the heart of the business, with the brand''s own locally roasted blend made into espresso drinks by the café''s baristas, along with teas and other hot and cold drinks. The breakfast menu runs all day, so eggs, toast and other morning favourites are available whenever the craving strikes. At lunchtime, the kitchen serves heartier dishes such as burgers, alongside freshly baked goods for a lighter bite. The modern, relaxed space suits a range of visits, from a quick takeaway coffee before work to a sit-down meal with friends or a few hours working on a laptop. Its location along the Esplanade makes it an easy meeting point for those living and working in Century City. Bootlegger Coffee Company is at Shop 5, 5 Esplanade Road, Century City, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'bootlegger-coffee-company-century-city' AND description = 'Bootlegger Coffee Company in Century City is a specialty coffee cafe serving all-day breakfast and lunch seven days a week.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
